using System;using System.Linq;using System.Collections.Generic;using Mono.Cecil;
class SearchIL{static IEnumerable<TypeDefinition> All(IEnumerable<TypeDefinition> ts){foreach(var t in ts){yield return t;foreach(var n in All(t.NestedTypes))yield return n;}}static void Main(string[] a){using(var asm=AssemblyDefinition.ReadAssembly(a[0]))foreach(var m in All(asm.MainModule.Types).SelectMany(t=>t.Methods).Where(m=>m.HasBody)){var matched=m.Body.Instructions.Where(i=>i.Operand!=null && i.Operand.ToString().IndexOf(a[1],StringComparison.OrdinalIgnoreCase)>=0).ToList();if(matched.Count==0)continue;Console.WriteLine(m.FullName);foreach(var i in a.Length>2?m.Body.Instructions:matched.AsEnumerable())Console.WriteLine(i);}}}
